/* BISM4RCK-KUN3H0 2026 */ include app_path('views/layouts/header.php'); ?><div class="container-fluid"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2>Walk-In Visitor</h2><div class="text-muted">No government ID required. Register the visitor, then use the six-character Visitor ID or barcode to check them in.</div></div></div><div class="row g-3"><div class="col-xl-6"><div class="gh-card p-4"><h5>Register Walk-In</h5><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="col-md-6"><label>Visitor Name</label><input class="form-control" name="visitor_name" required></div><div class="col-md-6"><label>Contact Number</label><input class="form-control" name="contact_number"></div><div class="col-12"><label>Vehicle(s) <span class="text-muted">(optional)</span></label><div id="walkinVehicles"><div class="row g-2 walkin-vehicle mb-2"><div class="col-md-5"><input class="form-control" name="vehicle_plate[]" placeholder="Plate"></div><div class="col-md-3"><select class="form-select" name="vehicle_type[]"><option>car</option><option>motorcycle</option><option>truck</option><option>other</option></select></div><div class="col-md-2"><input class="form-control" type="number" min="1" value="1" name="vehicle_people[]" placeholder="People"></div><div class="col-md-2"><button type="button" class="btn btn-outline-danger w-100 remove-walkin d-none">Remove</button></div></div></div><button type="button" id="addWalkinVehicle" class="btn btn-sm btn-outline-primary rounded-pill">+ Add vehicle</button></div><div class="col-12"><label>Purpose</label><input class="form-control" name="purpose" required></div><div class="col-12"><button class="btn gh-primary rounded-pill">Register Walk-In</button></div></form><script>document.addEventListener('DOMContentLoaded',()=>{const list=document.getElementById('walkinVehicles'),add=document.getElementById('addWalkinVehicle');if(!list||!add)return;add.addEventListener('click',()=>{const row=list.querySelector('.walkin-vehicle').cloneNode(true);row.querySelectorAll('input').forEach(i=>i.value=i.name.includes('people')?'1':'');row.querySelector('select').value='car';row.querySelector('.remove-walkin').classList.remove('d-none');list.appendChild(row);});list.addEventListener('click',e=>{if(e.target.classList.contains('remove-walkin')){e.target.closest('.walkin-vehicle').remove();}});});</script><?php if($created): ?><hr><div class="alert alert-success"><strong>Visitor ID: <?=e($created['visitor_id'])?></strong><div class="small">Give this ID to the visitor or scan the barcode below.</div></div><div class="credential-card"><svg id="walkInBarcode" class="w-100"></svg></div><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script><script>document.addEventListener('DOMContentLoaded',()=>JsBarcode('#walkInBarcode',<?=json_encode($created['barcode_token'])?>,{format:'CODE128',displayValue:true,height:90,margin:12}));</script><button class="btn btn-outline-secondary rounded-pill" onclick="window.print()">Print / Save</button><?php endif;?></div></div><div class="col-xl-6"><div class="gh-card p-4"><h5>Check In Walk-In</h5><form method="post" class="d-grid gap-3"><?=csrf_field()?><input type="hidden" name="action" value="checkin"><div><label>Visitor ID</label><input class="form-control form-control-lg text-uppercase" name="visitor_id" maxlength="6" placeholder="ABC234"></div><div class="text-center text-muted">or scan barcode</div><div><label>Barcode Token</label><input class="form-control form-control-lg" name="barcode_token" placeholder="Scan barcode here"></div><button class="btn btn-success btn-lg rounded-pill">Check In Walk-In</button></form><?php if($lookup): ?><div class="mt-4 p-3 bg-light rounded-4"><strong><?=e($lookup['visitor_name'])?></strong><div class="small text-muted">Visitor ID <?=e($lookup['visitor_id'])?> · <?=e($lookup['purpose_of_visit'])?></div></div><?php endif;?></div></div></div></div><?php include app_path('views/layouts/footer.php'); ?>
